#!/usr/bin/env node
// ============================================================
// PallettAI Studio — GEO / AI-search visibility smoke test
// (llms.txt + robots.txt AI-crawler policy + AI-search grade)
//
// Answer engines now introduce businesses directly instead of
// listing links, so the export gained an answer layer. The suite
// is weighted the way the risk is:
//
//   1. THE FILE IS TRUE. llms.txt is generated by the real
//      builder from a real project: name, summary, page links,
//      FAQ passages, contact details, updated stamp. It must
//      never claim something the project does not say.
//   2. IT IS SAFE BY DEFAULT. Escaping, cap at 12 FAQs, one
//      file shipped whether or not a live URL is set, robots.txt
//      naming the AI crawlers explicitly — and a site which never
//      asked for any of this still exports unchanged apart from
//      the new file.
//   3. THE AUDIT CANNOT PROMISE MORE THAN THE FILE DELIVERS.
//      Every GEO finding must name something the export actually
//      carries, and a site with no answer-layer content must
//      score worse than one with it.
//
// Fully offline. Run: node scripts/geo-visibility-smoke.js
// ============================================================

'use strict';

const path = require('path');
const ROOT = path.join(__dirname, '..');

let failed = 0;
function ok(name, cond, detail) {
  console.log((cond ? '  \u2713 ' : '  \u2717 ') + name + (!cond && detail ? '  -> ' + detail : ''));
  if (!cond) failed++;
}

global.DB = require(path.join(ROOT, 'data', 'db.js'));
const Builder = require(path.join(ROOT, 'modules', 'builder.js'));

function mkProject(siteExtra, sections) {
  const site = Object.assign({
    name: 'Northwind Joinery',
    tagline: 'Bespoke kitchens, built to last',
    metaDescription: 'Northwind Joinery designs and builds bespoke kitchens in Sheffield.',
    palette: 'midnight',
    font: 'inter',
    url: 'https://northwind.example',
    email: 'hi@northwind.example',
    phone: '+44 114 555 0100',
    area: 'Sheffield',
    socials: [{ icon: 'x', url: 'https://x.com/northwind' }],
    pages: [
      {
        id: 'home', name: 'Home', slug: 'index', sections: sections || [
          { type: 'hero', title: 'Bespoke kitchens', subtitle: 'Hand-built', items: [] },
          { type: 'faq', title: 'Questions', items: [
            { title: 'How long does a kitchen take?', text: 'Eight to ten weeks from survey to fit.' },
            { title: 'Do you offer finance?', text: 'Yes — 0% finance over twelve months.' },
            { title: 'Which areas do you cover?', text: 'Sheffield and the Peak District.' },
            { title: 'Is there a guarantee?', text: 'Ten years on every fitted kitchen.' }
          ] }
        ]
      },
      { id: 'p2', name: 'Pricing', slug: 'pricing', sections: [{ type: 'pricing', title: 'Prices', items: [] }] }
    ]
  }, siteExtra || {});
  return { id: 'p1', name: site.name, suites: [], site };
}

// ---- 1. llms.txt is generated and truthful ---------------------------------
console.log('\n1. llms.txt content');

const full = mkProject();
const extras = Builder.seoExtras(full, {});
const llm = extras.find((f) => f.name === 'llms.txt');
ok('llms.txt ships from seoExtras', !!llm, extras.map((f) => f.name).join(','));
if (llm) {
  const t = llm.content;
  ok('names the site as a top-level heading', t.includes('# Northwind Joinery'));
  ok('leads with the meta description as the summary', t.includes('> Northwind Joinery designs and builds'));
  ok('advertises the live URL', t.includes('Site: https://northwind.example/'));
  ok('links the extra page', t.includes('](https://northwind.example/pricing.html)') && t.includes('## Pages'));
  ok('carries the FAQ passages verbatim', t.includes('### How long does a kitchen take?') && t.includes('Eight to ten weeks from survey to fit.'));
  ok('ships contact details as plain text', t.includes('Email: hi@northwind.example') && t.includes('Phone: +44 114 555 0100') && t.includes('Serves: Sheffield'));
  ok('carries the social profile', t.includes('https://x.com/northwind'));
  ok('stamps an Updated date', /Updated: \d{4}-\d{2}-\d{2}\./.test(t));
  ok('Markdown-safe: strips link brackets from copy', !t.includes('[[') && !t.includes(']]'));
}

// ---- 2. safe by default ----------------------------------------------------
console.log('\n2. Safety and defaults');

const noUrl = Builder.seoExtras(mkProject({ url: '', metaDescription: '' }), {});
const llm2 = noUrl.find((f) => f.name === 'llms.txt');
ok('llms.txt still ships without a live URL', !!llm2);
if (llm2) {
  ok('falls back to relative page links', llm2.content.includes('](pricing.html)'));
  ok('never mentions the sitemap-less URL', !llm2.content.includes('https://northwind.example'));
  ok('tagline stands in when there is no meta description', !llm2.content.includes('> Northwind Joinery designs') && llm2.content.includes('> Bespoke kitchens, built to last'));
}
const bare = mkProject({ email: '', phone: '', area: '', socials: [] }, [{ type: 'hero', title: 'Hi', items: [] }]);
const llm3 = Builder.seoExtras(bare, {}).find((f) => f.name === 'llms.txt');
ok('a bare site still gets a valid file', !!llm3 && llm3.content.startsWith('# Northwind Joinery'));
if (llm3) ok('a bare site claims no FAQ or contact section', !llm3.content.includes('## Frequently asked questions') && !llm3.content.includes('## Contact'));
const empty = Builder.seoExtras({ id: 'p0', name: 'Blank', suites: [], site: { name: 'Blank', palette: 'midnight', font: 'inter', pages: [] } }, {});
ok('an empty project does not throw', empty.some((f) => f.name === 'llms.txt'));

console.log('\n3. robots.txt AI-crawler policy');
const robots = extras.find((f) => f.name === 'robots.txt');
ok('robots.txt generated', !!robots);
if (robots) {
  ok('names GPTBot explicitly', /User-agent: GPTBot\nAllow: \//.test(robots.content));
  ok('names ClaudeBot, PerplexityBot and Google-Extended', robots.content.includes('User-agent: ClaudeBot') && robots.content.includes('User-agent: PerplexityBot') && robots.content.includes('User-agent: Google-Extended'));
  ok('keeps the universal rule and the sitemap', robots.content.startsWith('User-agent: *\nAllow: /') && robots.content.includes('Sitemap: https://northwind.example/sitemap.xml'));
}

// ---- 4. the audit matches the file -----------------------------------------
console.log('\n4. AI-search (GEO) audit');

const good = Builder.geoAudit(full, Builder.pages(full), {});
ok('the well-fed site scores A', good.score >= 88 && good.letter === 'A', good.score + '/' + good.letter);
ok('the good site reports only positive info', good.findings.every((f) => f.level === 'info'), JSON.stringify(good.findings.filter((f) => f.level !== 'info')));

const thin = Builder.geoAudit(mkProject({ metaDescription: '', area: '', phone: '', email: '', socials: [] }, [{ type: 'hero', title: 'Hi', items: [] }]), null, {});
ok('a site with no answer content scores meaningfully below the well-fed one', thin.score <= good.score - 15 && thin.letter !== 'A', thin.score + '/' + thin.letter + ' vs ' + good.score + '/' + good.letter);
ok('names the missing meta description', thin.findings.some((f) => f.level === 'warn' && /No meta description/.test(f.msg)));
ok('names the missing FAQ passages', thin.findings.some((f) => f.level === 'warn' && /No question-shaped content/.test(f.msg)));
ok('names the missing plain-text contact route', thin.findings.some((f) => f.level === 'warn' && /No plain-text contact/.test(f.msg)));

const shortFaq = Builder.geoAudit(mkProject({}, [
  { type: 'hero', title: 'Hi', items: [] },
  { type: 'faq', title: 'FAQ', items: [{ title: 'One?', text: 'Yes.' }] }
]), null, {});
ok('two-to-three FAQs gets a gentle note, not a warning', shortFaq.findings.some((f) => f.level === 'info' && /FAQ entries/.test(f.msg)) && !shortFaq.findings.some((f) => /No question-shaped/.test(f.msg)));

const faq30 = mkProject({}, [
  { type: 'faq', title: 'FAQ', items: Array.from({ length: 30 }, (_, i) => ({ title: 'Q' + i + '?', text: 'A' + i + '.' })) }
]);
const capped = Builder.seoExtras(faq30, {}).find((f) => f.name === 'llms.txt');
if (capped) ok('FAQ list is capped (12) to keep the file light', (capped.content.match(/### /g) || []).length === 12, String((capped.content.match(/### /g) || []).length));

console.log('\n5. The audit cannot promise more than the export ships');

const thinProject = mkProject({ metaDescription: '', phone: '', area: '', email: '', socials: [] }, [{ type: 'hero', title: 'Hi', items: [] }]);
const thinFile = Builder.seoExtras(thinProject, {}).find((f) => f.name === 'llms.txt');
ok('a thin site really has no contact section in its file', thinFile && !thinFile.content.includes('## Contact'));
ok('a thin site really has no FAQ section in its file', thinFile && !thinFile.content.includes('## Frequently asked questions'));
const thinAudit = Builder.geoAudit(thinProject, null, {});
ok('its audit says so', thinAudit.findings.some((f) => /No question-shaped/.test(f.msg)) && thinAudit.findings.some((f) => /No plain-text contact/.test(f.msg)));

console.log('\n6. The plumbing is four files deep');

const appSrc = require('fs').readFileSync(path.join(ROOT, 'app.js'), 'utf8');
const proofSrc = require('fs').readFileSync(path.join(ROOT, 'data', 'proof.js'), 'utf8');
const indexSrc = require('fs').readFileSync(path.join(ROOT, 'index.html'), 'utf8');
ok('plain export appends llms.txt', /exportFileList[\s\S]{0,400}llms\.txt/.test(appSrc));
ok('delivery audits carry the aiSearch report', /Readability\.grade\(c\); \} catch[\s\S]{0,300}aiSearch/.test(appSrc));
ok('the export report names llms.txt to the user', appSrc.includes('AI answer engines'));
ok('client handoff ships llms.txt too', /how-to-edit\.html[\s\S]{0,300}llms\.txt/.test(appSrc));
ok('the composite grade weights AI answer visibility', proofSrc.includes('aiSearch: 11'));
ok('the label exists for the report table', proofSrc.includes("'AI answer visibility'"));
ok('builder.js is still loaded by the shell', indexSrc.includes('modules/builder.js'));

console.log('\n' + (failed ? failed + ' check(s) FAILED' : 'All checks passed.'));
process.exit(failed ? 1 : 0);
